node -e "
const fs=require('fs');const p='src/data/products.ts';let s=fs.readFileSync(p,'utf8');
const facts={'canvas-field-tote':'18 OZ CANVAS','waxed-day-pack':'22 L CAPACITY','weekender-duffel':'45 L CAPACITY','merino-crew-sweater':'100% MERINO','heavyweight-pocket-tee':'240 GSM JERSEY','cotton-chore-coat':'COTTON TWILL','enamel-camp-mug':'350 ML STEEL','cast-iron-skillet':'PRE-SEASONED IRON','linen-tea-towels':'100% LINEN','leather-key-ring':'VEG-TANNED LEATHER','ribbed-wool-beanie':'WOOL BLEND'};
for(const [slug,fact] of Object.entries(facts)){const re=new RegExp(\"(slug: '\"+slug+\"',[\\\\s\\\\S]*?tone: '\\\\w+',)\");if(!re.test(s))throw slug;s=s.replace(re,\"\$1\n    fact: '\"+fact+\"',\");}
s=s.replace('  tone: Tone;\n}','  tone: Tone;\n  /** One fact for the spec plate caption, at most 18 characters. */\n  fact: string;\n}');
